using System.Linq;

namespace Acme.Billing;

public sealed class InvoiceReport
{
    private readonly BillingDbContext _db;

    public string Render(int customerId)
    {
        var invoices = _db.Invoices.Where(invoice => invoice.CustomerId == customerId);
        var total = invoices.Sum(invoice => invoice.Amount);
        var count = invoices.Count();
        return $"{count} invoices, {total:C}";
    }
}

