public string Render(int customerId)
{
    var invoices = _db.Invoices
        .Where(invoice => invoice.CustomerId == customerId)
        .ToList();
    var total = invoices.Sum(invoice => invoice.Amount);
    var count = invoices.Count;
    return $"{count} invoices, {total:C}";
}

public string Render(int customerId)
{
    var summary = _db.Invoices
        .Where(invoice => invoice.CustomerId == customerId)
        .GroupBy(invoice => invoice.CustomerId)
        .Select(group => new { Count = group.Count(), Total = group.Sum(invoice => invoice.Amount) })
        .SingleOrDefault();
    var count = summary?.Count ?? 0;
    var total = summary?.Total ?? 0m;
    return $"{count} invoices, {total:C}";
}
